package kerberos

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"sync"
	"time"
)

const (
	FlagForwardable = 0x40000000
	FlagProxiable   = 0x10000000
	FlagRenewable   = 0x00800000
	FlagConstrained = 0x00080000
)

type TenantConfig struct {
	TenantID        string
	Realm           string
	MaxDelegation   int
	AllowForwarding bool
	MasterKey       []byte
}

type TicketGrantingTicket struct {
	ClientPrincipal string
	TenantID        string
	Realm           string
	Flags           uint32
	SessionKey      []byte
	AuthTime        time.Time
	EndTime         time.Time
	DelegationCount int
	TargetService   string
}

type DelegationContext struct {
	mu              sync.RWMutex
	tenants         map[string]*TenantConfig
	activeDelegations map[string]int
}

func NewDelegationContext() *DelegationContext {
	return &DelegationContext{
		tenants:           make(map[string]*TenantConfig),
		activeDelegations: make(map[string]int),
	}
}

func (dc *DelegationContext) RegisterTenant(cfg *TenantConfig) error {
	dc.mu.Lock()
	defer dc.mu.Unlock()
	if len(cfg.MasterKey) != 32 {
		return errors.New("master key must be 256 bits")
	}
	dc.tenants[cfg.TenantID] = cfg
	return nil
}

func (dc *DelegationContext) deriveServiceKey(tenant *TenantConfig, service string) ([]byte, error) {
	mac := hmac.New(sha256.New, tenant.MasterKey)
	mac.Write([]byte(tenant.TenantID))
	mac.Write([]byte(service))
	mac.Write([]byte(tenant.Realm))
	return mac.Sum(nil), nil
}

func (dc *DelegationContext) validateDelegationPolicy(tgt *TicketGrantingTicket, tenant *TenantConfig) error {
	if tgt.DelegationCount >= tenant.MaxDelegation {
		return errors.New("delegation depth exceeded")
	}
	if !tenant.AllowForwarding && (tgt.Flags&FlagForwardable != 0) {
		return errors.New("forwarding not allowed for tenant")
	}
	return nil
}

func (dc *DelegationContext) checkConstrainedDelegation(tgt *TicketGrantingTicket, targetService string) bool {
	if tgt.Flags&FlagConstrained != 0 {
		return tgt.TargetService == targetService
	}
	return true
}

func (dc *DelegationContext) validateTicketValidity(tgt *TicketGrantingTicket) error {
	now := time.Now()
	if !tgt.AuthTime.IsZero() && now.Before(tgt.AuthTime) {
		return errors.New("ticket not yet valid")
	}
	if !tgt.EndTime.IsZero() && !now.Before(tgt.EndTime) {
		return errors.New("ticket expired")
	}
	return nil
}

func (dc *DelegationContext) IssueServiceTicket(tgt *TicketGrantingTicket, targetService string) (*TicketGrantingTicket, error) {
	dc.mu.RLock()
	tenant, exists := dc.tenants[tgt.TenantID]
	dc.mu.RUnlock()

	if !exists {
		return nil, errors.New("tenant not found")
	}

	if err := dc.validateTicketValidity(tgt); err != nil {
		return nil, err
	}

	if err := dc.validateDelegationPolicy(tgt, tenant); err != nil {
		return nil, err
	}

	if !dc.checkConstrainedDelegation(tgt, targetService) {
		return nil, errors.New("constrained delegation target mismatch")
	}

	serviceKey, err := dc.deriveServiceKey(tenant, targetService)
	if err != nil {
		return nil, err
	}

	newFlags := dc.computeDelegatedFlags(tgt.Flags, tenant)

	sessionKey := make([]byte, 32)
	if _, err := rand.Read(sessionKey); err != nil {
		return nil, err
	}

	newTicket := &TicketGrantingTicket{
		ClientPrincipal: tgt.ClientPrincipal,
		TenantID:        tgt.TenantID,
		Realm:           tgt.Realm,
		Flags:           newFlags,
		SessionKey:      sessionKey,
		AuthTime:        tgt.AuthTime,
		EndTime:         time.Now().Add(8 * time.Hour),
		DelegationCount: tgt.DelegationCount + 1,
		TargetService:   targetService,
	}

	_ = serviceKey
	return newTicket, nil
}

func (dc *DelegationContext) computeDelegatedFlags(originalFlags uint32, tenant *TenantConfig) uint32 {
	flags := originalFlags
	if !tenant.AllowForwarding {
		flags &^= FlagForwardable
	}
	flags |= FlagConstrained
	return flags
}

func (dc *DelegationContext) CrossTenantDelegation(tgt *TicketGrantingTicket, targetTenantID string, targetService string) (*TicketGrantingTicket, error) {
	dc.mu.RLock()
	sourceTenant, srcExists := dc.tenants[tgt.TenantID]
	targetTenant, tgtExists := dc.tenants[targetTenantID]
	dc.mu.RUnlock()

	if !srcExists || !tgtExists {
		return nil, errors.New("tenant not found")
	}

	if err := dc.validateDelegationPolicy(tgt, sourceTenant); err != nil {
		return nil, err
	}

	if err := dc.validateDelegationPolicy(tgt, targetTenant); err != nil {
		return nil, err
	}

	newTicket, err := dc.IssueServiceTicket(tgt, targetService)
	if err != nil {
		return nil, err
	}

	newTicket.TenantID = targetTenantID
	newTicket.Realm = targetTenant.Realm

	return newTicket, nil
}

func (dc *DelegationContext) EncryptTicket(ticket *TicketGrantingTicket) ([]byte, error) {
	dc.mu.RLock()
	tenant, exists := dc.tenants[ticket.TenantID]
	dc.mu.RUnlock()

	if !exists {
		return nil, errors.New("tenant not found")
	}

	serviceKey, err := dc.deriveServiceKey(tenant, ticket.TargetService)
	if err != nil {
		return nil, err
	}

	plaintext := dc.serializeTicket(ticket)

	block, err := aes.NewCipher(serviceKey)
	if err != nil {
		return nil, err
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}

	nonce := make([]byte, gcm.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		return nil, err
	}

	return gcm.Seal(nonce, nonce, plaintext, nil), nil
}

func (dc *DelegationContext) serializeTicket(ticket *TicketGrantingTicket) []byte {
	buf := make([]byte, 0, 256)
	buf = append(buf, []byte(ticket.ClientPrincipal)...)
	buf = append(buf, 0)
	buf = append(buf, []byte(ticket.TenantID)...)
	buf = append(buf, 0)
	buf = append(buf, []byte(ticket.Realm)...)
	buf = append(buf, 0)
	flagsBytes := make([]byte, 4)
	binary.BigEndian.PutUint32(flagsBytes, ticket.Flags)
	buf = append(buf, flagsBytes...)
	buf = append(buf, ticket.SessionKey...)
	return buf
}
